function setQBMaterialQty(i,val){
  const m=window._qb.materials[i];if(!m)return;
  if(val===''||val==null){m.quantity='';qbFastRecalc();return;}
  const v=Number(val);
  const cov=Number(m.coveragePerUOM)||0;
  if(cov>1&&v>0){const cartons=Math.ceil(v/cov);m.quantity=Math.round(cartons*cov*100)/100;}
  else{m.quantity=v;}
  const isRolled=(Number(m.rollWidth)>0)||(m.purchaseUOM||'').toLowerCase()==='roll'||((m.matNum||'').toUpperCase().startsWith('RMAT'));
  const w=Number(m.rollWidth)||0;
  if(isRolled&&w>0&&Number(m.quantity)>0){const linearFt=(Number(m.quantity)*9)/w;m.lengthFt=Math.floor(linearFt);m.lengthIn=Math.round((linearFt-Math.floor(linearFt))*12*100)/100;m.linearFt=Math.round(linearFt*100)/100;}
  qbFastRecalc();
}

index:fn:_qbInchFrac.code:
function _qbInchFrac(dec){
  if(dec==null)return '';
  const sixteenths=Math.round(Number(dec)*16);
  if(sixteenths<=0)return '';
  const whole=Math.floor(sixteenths/16);
  let frac=sixteenths-whole*16;
  if(frac===0)return whole>0?String(whole):'';
  let n=frac,d=16;
  while(n%2===0){n/=2;d/=2;}
  return (whole>0?whole+' ':'')+n+'/'+d;
}

