function qbBuildQtyExtraHtml(m,i){
  const cov=Number(m.coveragePerUOM)||0;
  const cartons=cov>1?Math.ceil((Number(m.quantity)||0)/cov):0;
  const isRolled=(Number(m.rollWidth)>0)||(m.purchaseUOM||'').toLowerCase()==='roll'||((m.matNum||'').toUpperCase().startsWith('RMAT'));
  if(isRolled){
    const lf=Number(m.lengthFt)||0;
    const li=Number(m.lengthIn)||0;
    const hasL=(lf>0||li>0);
    const inDisp=_qbInchFrac(li);
    const lDisp=hasL?(inDisp?lf+"' "+inDisp+'"':lf+"'"):'';
    if(hasL){
      return '<div style="font-size:12px;margin-top:4px;line-height:1.4"><span style="color:var(--primary);font-weight:700;cursor:pointer" onclick="qbEditRollDimensions('+i+')" title="Click to edit roll dimensions">📐 '+lDisp+'</span></div>';
    }
    return '<div style="font-size:12px;margin-top:4px;line-height:1.4"><span style="color:var(--danger);font-weight:600;cursor:pointer;text-decoration:underline;text-decoration-style:dotted" onclick="qbEditRollDimensions('+i+')" title="Click to set roll dimensions">⚠ set length</span></div>';
  } else if(cartons>0){
    const uomLbl=m.purchaseUOM||'unit';
    const plural=cartons===1?uomLbl:(/box$/i.test(uomLbl)?uomLbl+'es':uomLbl+'s');
    const sqft=(Number(m.quantity)||0).toFixed(2);
    const covUom=m.costUOM||m.coverageUOM||'SqFt';
    return '<div style="font-size:12px;margin-top:4px;line-height:1.4"><span style="color:var(--primary);font-weight:700">📦 '+cartons+' '+plural+'</span> <span style="color:var(--gray)">= '+sqft+' '+covUom+'</span></div>';
  }
  return '';
}

