      else {labReqPr+=l.totalPrice;labReqCost+=l.totalCost;secLabSub[sIdx]=(secLabSub[sIdx]||0)+l.totalPrice;}
    }
    setInputVal('qb-tot-lab-'+i,(Number(l.totalPrice)||0).toFixed(2));
  });
