  (qb.materials||[]).forEach(m=>{if(m.isBundle){const _be=document.getElementById('qb-bundle-total-'+m.bundleId);if(_be)_be.textContent=(_bundleTot[m.bundleId]||0).toFixed(2);}});

  qb.materialsTotalPrice=matReqPr;qb.materialsTotalCost=matReqCost;
  qb.laborTotalPrice=labReqPr;qb.laborTotalCost=labReqCost;
  qb.materialsOptionalPrice=matOptPr;qb.materialsOptionalCost=matOptCost;
  qb.laborOptionalPrice=labOptPr;qb.laborOptionalCost=labOptCost;
