function qbRefreshDownPaymentAmt(){
  const qb=window._qb;
  if(!qb)return;
  const matReq=Number(qb.materialsTotalPrice)||0;
  const labReq=Number(qb.laborTotalPrice)||0;
  const taxRate=Number(qb.taxRate)||0;
  const taxExempt=!!qb.taxExempt;
