index:fn:_quoteSecActive.code:
function _quoteSecActive(o,sIdx){
  const secs=(o&&o.sections)||[];
  const sec=secs[sIdx];if(!sec)return true;
  const cg=String((sec.choiceGroup||'')).trim();if(!cg)return true;
  const members=secs.map(function(s,i){return String((s&&s.choiceGroup)||'').trim()===cg?i:-1;}).filter(function(i){return i>=0;});
  if(members.length<2)return true;
  return _choiceActiveIdxs(secs,members).indexOf(sIdx)>=0;
}

index:fn:_choiceActiveIdxs.code:
function _choiceActiveIdxs(sections,members){
  if(!Array.isArray(members)||!members.length)return [];
  const secs=sections||[];
  const sel=members.filter(function(i){return secs[i]&&secs[i].isChoiceSelected===true;});
  if(sel.length)return sel;
  if(members.some(function(i){return secs[i]&&secs[i].chooseOne===false;}))return members.slice();
  let d=members.find(function(i){return secs[i]&&secs[i].isChoiceDefault;});
  if(d==null)d=members[0];
  return [d];
}

index:fn:_choiceGroups.code:
function _choiceGroups(sections){
  const map={};
  (sections||[]).forEach(function(s,i){
    const cg=String((s&&s.choiceGroup)||'').trim();if(!cg)return;
    if(!map[cg])map[cg]=[];map[cg].push(i);
  });
  Object.keys(map).forEach(function(cg){if(map[cg].length<2)delete map[cg];});
  return map;
}

