function _mqTotals(q){
  const secs=q.sections||[];
  const isOpt=(s)=>!!(secs[s||0]&&secs[s||0].optional);
  const isMC=(s)=>!!(secs[s||0]&&secs[s||0].multipleChoice);
  const mcDrop=(type,sIdx,gi,row)=>{
    if(!isMC(sIdx))return false;
    if(row&&row.bundleId&&!row.isBundle){
      const p=(q.materials||[]).findIndex(x=>x&&x.isBundle&&x.bundleId===row.bundleId);
      if(p>=0)return !qbMcIsChosen(q,sIdx,'mat',p);
    }
    return !qbMcIsChosen(q,sIdx,type,gi);
  };
  let mat=0,lab=0,opt=0;
  (q.materials||[]).forEach((m,gi)=>{const s=m._section||0;if(!_mqSecActive(q,s))return;if(mcDrop('mat',s,gi,m))return;const v=(m.quantity||0)*(m.retailPrice||0);if(isOpt(s))opt+=v;else mat+=v;});
  (q.labors||[]).forEach((l,gi)=>{const s=l._section||0;if(!_mqSecActive(q,s))return;if(mcDrop('lab',s,gi,l))return;const v=(l.retailPrice||0)*(l.quantity||1);if(isOpt(s))opt+=v;else lab+=v;});
  const r2=(n)=>Math.round(n*100)/100;
  const subtotal=mat+lab;const taxRate=q.taxRate??0.076;const tax=r2(mat*taxRate);
  return {subtotal:r2(subtotal),tax,total:r2(subtotal+tax),optional:r2(opt)};
}

