function qbChosenSectionsAndRows(q){
  const sections=(q&&q.sections)||[];
  const selOpts=Array.isArray(q&&q.selectedOptions)?q.selectedOptions:null;
  const noSel=!selOpts||!selOpts.length;
  const selOptIdxs=new Set();
  const selChoiceIdxs=new Set();
  const selMcRow={}; // {sIdx:rowKey}
  if(selOpts){
    selOpts.forEach(function(o){
      if(!o)return;
      const i=Number(o.idx);
      if(o.mode==='optional')selOptIdxs.add(i);
      else if(o.mode==='choice')selChoiceIdxs.add(i);
      else if(o.mode==='mc'&&o.rowKey)selMcRow[i]=o.rowKey;
    });
  }
  // Build choice-group → members map (only groups with 2+ members count).
  const cgMap=_choiceGroups(sections);
  const chosenSections=new Set();
  sections.forEach(function(s,i){
    const cg=String((s&&s.choiceGroup)||'').trim();
    if(cg && cgMap[cg] && cgMap[cg].length>=2){
      // Multi-member choice group. The customer may have picked more than one
      // member — every pick arrives as its own selectedOptions entry, and all
      // of them go to the work order and the invoice.
      if(selChoiceIdxs.has(i)){chosenSections.add(i);return;}
      // No customer selection captured yet (admin manual-approve, or a PDF of
      // an un-approved quote). Fall back to whatever the quote itself is
      // showing, so the paperwork never quotes a smaller scope than the page
      // the customer is looking at.
      if(noSel&&_choiceActiveIdxs(sections,cgMap[cg]).indexOf(i)>=0)chosenSections.add(i);
      return;
    }
    if(s&&s.optional){
      if(selOptIdxs.has(i))chosenSections.add(i);
      else if(noSel)chosenSections.add(i);
      return;
    }
    chosenSections.add(i);
  });
  // Safety net: every choice group should have at least one chosen member.
  // If the customer's selection didn't pick one (and there was a selection),
  // fall back to the default member of that group so WO/invoice don't end
  // up empty for that group.
  Object.keys(cgMap).forEach(function(cg){
    const mems=cgMap[cg];if(mems.length<2)return;
    if(mems.some(function(i){return chosenSections.has(i);}))return;
    let def=mems.find(function(i){return sections[i]&&sections[i].isChoiceDefault;});
    if(def==null)def=mems[0];
    chosenSections.add(def);
  });
  return {chosenSections:chosenSections, mcRow:selMcRow};
}

index:fn:qbFilterChosenItems.code:
function qbFilterChosenItems(q,chosen){
  const cs=chosen.chosenSections;const mcRow=chosen.mcRow||{};
  const sections=(q&&q.sections)||[];
  const allMats=(q&&q.materials)||[];
  const allLabs=(q&&q.labors)||[];
  const outMats=[];const outLabs=[];
  // Iterate per-section so MC row indices line up with the public page.
  const sIdxs=Array.from(new Set([].concat(
    allMats.map(function(m){return m._section||0;}),
    allLabs.map(function(l){return l._section||0;}),
    sections.map(function(_,i){return i;})
  )));
  sIdxs.forEach(function(sIdx){
    if(!cs.has(sIdx))return;
    const sec=sections[sIdx]||{};
    const secMats=allMats.filter(function(m){return (m._section||0)===sIdx;});
    const secLabs=allLabs.filter(function(l){return (l._section||0)===sIdx;});
    if(sec.multipleChoice && mcRow[sIdx]){
      const key=String(mcRow[sIdx]);
      const m=key.match(/^mat-(\d+)$/);const l=key.match(/^lab-(\d+)$/);
      if(m){const idx=Number(m[1]);if(secMats[idx])outMats.push(secMats[idx]);}
      else if(l){const idx=Number(l[1]);if(secLabs[idx])outLabs.push(secLabs[idx]);}
    } else {
      secMats.forEach(function(m){outMats.push(m);});
      secLabs.forEach(function(x){outLabs.push(x);});
    }
  });
  return {mats:outMats, labs:outLabs};
}

