function applyCustomerSelectionToQuote(q){
  if(!q||!Array.isArray(q.sections))return;
  const selOpts=Array.isArray(q.selectedOptions)?q.selectedOptions:null;
  if(!selOpts||!selOpts.length)return;
  // Choice picks arrive as one entry PER selected member, so the whole group
  // has to be collected before anything is written. The per-entry loop this
  // replaces set isChoiceDefault=true on each pick in turn and false on every
  // other member of the group — so a customer who picked both options ended
  // up with only the last one live, and bought half of what they asked for.
  const picksByGroup={};
  selOpts.forEach(function(o){
    if(!o||o.mode!=='choice')return;
    const idx=Number(o.idx);
    const sec=q.sections[idx];if(!sec)return;
    const cg=String((sec.choiceGroup||'')).trim();if(!cg)return;
    if(!picksByGroup[cg])picksByGroup[cg]=[];
    if(picksByGroup[cg].indexOf(idx)<0)picksByGroup[cg].push(idx);
  });
