function _refreshQuoteStoredTotals(q){
  if(!q||!Array.isArray(q.materials)&&!Array.isArray(q.labors))return false;
  const t=_mqTotals(q);
  const same=(a,b)=>Math.abs((Number(a)||0)-(Number(b)||0))<0.005;
  if(same(q.subtotal,t.subtotal)&&same(q.tax,t.tax)&&same(q.total,t.total))return false;
