function completeJob(id,opts){const j=getJob(id);if(!j)return;
// Consume any inventory that was allocated for this job — decrement parent on-hand AND allocated (parent is source of truth).
(j.materials||[]).forEach(m=>{
  if(!m.allocatedFromInventory)return;
  if(m.materialsConsumedAt)return;
  const inv=m.invId?(data.inventory||[]).find(x=>x.id===m.invId):(m.matNum?(data.inventory||[]).find(x=>x.matNum===m.matNum):null);
  if(!inv)return;
  const consumed=Number(m.allocatedQty)||_coverageUnits(m.quantity,m.coveragePerUOM)||0;
  if(consumed<=0)return;
  inv.onHand=Math.max(0,(Number(inv.onHand)||0)-consumed);
  inv.allocated=Math.max(0,(Number(inv.allocated)||0)-consumed);
  if(inv.available!=null)inv.available=Math.max(0,(Number(inv.onHand)||0)-(Number(inv.allocated)||0));
  if(inv.remainingStock!=null)inv.remainingStock=inv.available;
  m.materialsConsumedAt=_todayISO();
});
// Status on completion: park at "Final Invoice" until the linked
// invoice is fully paid; then auto-advance to "Ready to be Paid"
// (see recordPayment). If an invoice tied to this WO is already
// paid at the moment of completion, skip the wait state.
const _anyInvPaid=(data.invoices||[]).some(i=>i.jobId===j.id&&i.status==='paid');
j.status=_anyInvPaid?'ready_to_be_paid':'final_invoice';
j.completedAt=_todayISO();
const _newLbl=JOB_STATUS_LABELS[j.status]||j.status;
addActivity(`Job ${j.number} → ${_newLbl}`);
