function _matMaybeAdvance(j){
  if(!j)return false;
  const ms=_jobMatState(j);
  if(!['order_materials','materials_ordered'].includes(j.status))return false;
  if(ms.total&&ms.allIn){
    if(j.scheduledDate){j.status='scheduled';addActivity(`Job ${j.number} → Scheduled (materials in, date already set)`);}
    else{j.status='ready_to_schedule';addActivity(`Job ${j.number} → Ready to Schedule (all materials in)`);}
    return true;
  }
  if(ms.ordered>0&&j.status==='order_materials'){j.status='materials_ordered';return true;}
  return false;
}

