  inv.payments.push(_payWithCheckNo({amount:amt,method:document.getElementById('acct-pay-method').value,date:document.getElementById('acct-pay-date').value},'acct-'));
  const tp=inv.payments.reduce((a,p)=>a+(Number(p.amount)||0),0);
  inv.status=tp>=(Number(inv.total)||0)?'paid':tp>0?'deposit':'unpaid';
