  // Job-linked bills that aren't already counted: PO-sourced payables mirror
  // the POs above, and commission payables mirror the commission line below.
  const jobPayables=payables.filter(p=>!p.poId&&p.source!=='po'&&p.source!=='commission'&&(p.category||'')!=='Commission');
  // …and they land in the bucket their CATEGORY names, exactly as a recorded
  // cost does. Every job bill used to fall into Supplies & other, so a
  // materials invoice entered in Accounting left the Materials bucket still
  // showing the quote — which reads as "nothing recorded yet" and invites
  // someone to enter the same materials a second time.
  const payBucket=p=>_jcBucket({category:p.category||'',kind:'other'});
  const matPayables=jobPayables.filter(p=>payBucket(p)==='material');
  const laborPayables=jobPayables.filter(p=>payBucket(p)==='labor');
  const otherPayables=jobPayables.filter(p=>{const b=payBucket(p);return b!=='material'&&b!=='labor';});
  const sumAmt=list=>list.reduce((s,p)=>s+(Number(p.amount)||0),0);
  const matPayCost=sumAmt(matPayables),laborPayCost=sumAmt(laborPayables);
  const otherCost=sumAmt(otherPayables)+jc.supply+jc.other;
  // What the card processor kept. Derived from the payments themselves, never
  // recorded as a cost row — a row would drift the moment a payment is edited,
  // and could be entered a second time by hand.
  const feeCost=invs.reduce((s,i)=>s+_invProcessingFees(i),0);
  // Buckets switch to actuals once anything real lands in them — a bill counts
  // as real, which is the whole point of the split above.
  const matActual=pos.length>0||jc.material>0||matPayCost>0;
  const matCost=matActual?poCost+jc.material+matPayCost:matQuoted;
  const laborActual=jc.labor>0||laborPayCost>0;
  if(laborActual)laborCost=jc.labor+laborPayCost;
  const basisMode=finSettings().commissionBasis||'profit';
  const preCommProfit=revenue-matCost-laborCost-otherCost-feeCost;
  const basisAmt=basisMode==='revenue'?revenue:preCommProfit;
  const reps=_jobRepShares(j).map(r=>Object.assign({},r,{basisAmt:basisAmt*r.share,amount:Math.max(0,basisAmt*r.share*(r.rate/100))}));
  const commission=reps.reduce((s,r)=>s+r.amount,0);
  const profit=preCommProfit-commission;
  const margin=revenue>0?(profit/revenue*100):0;
  const collected=invs.reduce((s,i)=>s+_invPaidAmt(i),0);
  const quotedProfit=retail-matQuoted-laborQuoted;
  return {revenue,revSource:invs.length?'invoice':'quoted',retail,tax,taxSource,invTotal,outstanding:Math.max(0,invTotal-collected),matQuoted,matCost,matActual,poCost,pos,jc,laborQuoted,laborCost,laborActual,otherCost,feeCost,otherPayables,matPayables,laborPayables,jobPayables,payables,commission,reps,profit,margin,invs,collected,quotedProfit,basisMode};
}

index:fn:_jcRollup.code:
function _jcRollup(jobId){
  const rows=_jcForJob(jobId);
  const out={labor:0,material:0,supply:0,other:0,total:0,paid:0,unpaid:0,rows};
  rows.forEach(c=>{
    const amt=_jcAmount(c);
    out[_jcBucket(c)]+=amt;
    out.total+=amt;
    if(c.paid)out.paid+=amt;else out.unpaid+=amt;
  });
  return out;
}

index:fn:_jcAmount.code:
function _jcAmount(c){
  if(!c)return 0;
  const amt=Number(c.amount);
  if(Number.isFinite(amt)&&amt!==0)return amt;
  return (Number(c.quantity)||0)*(Number(c.unitCost)||0);
}

index:fn:_jcBucket.code:
function _jcBucket(c){
  if(!c)return 'other';
  if(c.kind==='contractor')return 'labor';
  if(c.kind==='supply')return 'supply';
  // Freight is the cost of getting the material to the job, so it answers to
  // the material estimate rather than floating in "other".
  if(c.kind==='freight')return 'material';
  const cat=String(c.category||'').toLowerCase();
  if(cat==='materials'||cat==='material'||cat==='freight'||cat==='delivery')return 'material';
  if(cat==='labor'||cat==='subcontractor')return 'labor';
  return 'other';
}

index:fn:_jobRepShares.code:
function _jobRepShares(j){
  let src=null;
  const has=o=>o&&(o.salesRepId||o.salesRep||o.salesRepId2||o.salesRep2);
  if(has(j))src=j;
  if(!src&&j.quoteId){const q=getQuote(j.quoteId);if(has(q))src=q;}
  if(!src){const inv=(data.invoices||[]).find(i=>i.jobId===j.id&&has(i));if(inv)src=inv;}
  if(!src)return [];
  const out=[];
  const push=(id,name)=>{
    if(!id&&!name)return;
    const person=id?(data.contractors||[]).find(c=>c.id===id):((data.contractors||[]).find(c=>(c.name||'').toLowerCase()===String(name||'').toLowerCase()));
    out.push({repId:id||(person?person.id:''),name:name||(person?person.name:'')||'Sales Rep',rate:person&&person.commissionRate!=null?(Number(person.commissionRate)||0):0});
  };
  push(src.salesRepId,src.salesRep);
  push(src.salesRepId2,src.salesRep2);
  const share=out.length?1/out.length:0;
  out.forEach(r=>{r.share=share;r.key=r.repId||('name:'+r.name.toLowerCase());});
  return out;
}

index:fn:_payProcessingFee.code:
function _payProcessingFee(pay){
  if(!pay)return 0;
  if(pay.processingFee!=null&&isFinite(Number(pay.processingFee)))return Math.max(0,Number(pay.processingFee));
  if(!_isCardPayment(pay))return 0;
  const amt=Number(pay.amount)||0;
  if(amt<=0)return 0;
  const {pct,fixed}=_cardFeeRate();
  return Math.round((amt*pct/100+fixed)*100)/100;
}

index:fn:_cardFeeRate.code:
function _cardFeeRate(){
  const fs=(typeof finSettings==='function')?finSettings():{};
  const pct=Number(fs.cardFeePct);
  const fixed=Number(fs.cardFeeFixed);
  return {pct:isFinite(pct)&&pct>=0?pct:CARD_FEE_PCT_DEFAULT,
          fixed:isFinite(fixed)&&fixed>=0?fixed:CARD_FEE_FIXED_DEFAULT};
}

