(function(){
            // Invoice-only: the PAYMENT area, directly beneath Balance Due.
            // What it asks for follows the invoice's payment terms — see
            // computeDueNow / termRule above. The server recomputes the same
            // rule in api/public-invoice-intent.js and is authoritative for
            // the charge; this is the display of it.
            if(!INV_MODE || PDF_MODE) return '';
            const t = window.__invTotals || { grand:(Number(q.total)||0), paid:0, bal:(Number(q.total)||0) };
            // Totals come off the rendered rows (they account for selected
            // options); everything else off the invoice row.
            const due = computeDueNow({
              total: t.grand, payments: [{ amount: t.paid }],
              down_payment_pct: q.down_payment_pct,
              final_invoice: q.final_invoice,
              payment_terms: q.payment_terms,
              created_at: q.created_at,
            }, Date.now());
            const dueNow = due.dueNow, pct = due.pct;
            window.__payDueNow = dueNow;
            // When the full balance is only due later, say which day.
            const netDueOn = due.netDays != null ? fmtDate(plusDays(q.created_at, due.netDays)) : '';
            if(t.bal <= 0.005){
              return '<div class="pay-wrap"><div class="pay-h">PAYMENT</div>'
                + '<div class="pay-done"><div class="big">✓ Paid in Full</div><div class="meta-x">Thank you — no balance remains on this invoice.</div></div></div>';
            }
            if(dueNow < 0.5){
              const when = due.basis === 'net-pending' && netDueOn
                ? 'is due '+esc(netDueOn)
                : 'will be due upon completion';
              return '<div class="pay-wrap"><div class="pay-h">PAYMENT</div>'
                + '<div class="pay-none">No payment is due right now.<br>The remaining balance of <strong>'+fmt$(t.bal)+'</strong> '+when+'.</div></div>';
            }
            const remainAfter = Math.round((t.bal - dueNow)*100)/100;
            const termTxt = String(q.payment_terms||'').trim();
            const depositLbl = pct < 100
              ? pct+'% deposit' + (remainAfter > 0.005 ? ' — remaining '+fmt$(remainAfter)+' due upon completion' : '')
              : 'Balance due';
            const subLbl =
                due.basis === 'final'      ? 'Final invoice — full remaining balance'
              : due.basis === 'immediate'  ? esc(termTxt || 'Due on receipt')+' — full balance due now'
              : due.basis === 'net-due'    ? esc(termTxt)+' — full balance due'+(netDueOn ? ' as of '+esc(netDueOn) : '')
              : due.basis === 'net-pending'? depositLbl.replace('due upon completion', netDueOn ? 'due '+esc(netDueOn) : 'due upon completion')
              : depositLbl;
            return '<div class="pay-wrap"><div class="pay-h">PAYMENT</div>'
              + '<div class="pay-card">'
                + '<div class="pay-due-row"><span class="pay-due-lbl">Due Now</span><span class="pay-due-amt" id="pay-amt">'+fmt$(dueNow)+'</span></div>'
                + '<div class="pay-due-sub" id="pay-sub">'+subLbl+'</div>'
                + '<div class="pay-el-wrap"><div id="pay-element"><div class="pay-el-loading">Loading secure card form…</div></div></div>'
                + '<button id="pay-btn" class="pay-btn" disabled>💳 Pay '+fmt$(dueNow)+' by Card</button>'
                + '<div id="pay-err" class="pay-err"></div>'
                + '<div class="pay-note">🔒 Secure card payment powered by Stripe</div>'
              + '</div></div>';
          })()
